import { useEffect, useState, useRef, useCallback } from "react";
import {
  Button,
  Grid,
  IconButton,
  MenuItem,
  Select,
  Typography,
} from "@mui/material";
import Card from "@mui/material/Card";
import Box from "@mui/material/Box";
import TextField from "@mui/material/TextField";
import PageHeader from "src/@core/components/page-header";
import Translations from "src/layouts/components/Translations";
import { axiosInstance } from "src/network/adapter";
import { ApiEndPoints } from "src/network/endpoints";
import { DefaultPaginationSettings } from "src/constants/general.const";
import { toastError, toastSuccess } from "src/utils/utils";
import DialogConfirmation from "src/views/dialog/DialogConfirmation";
import { useLocation, useNavigate, useParams } from "react-router-dom";
import DialogOverviewFeatures from "src/views/dialog/IT-Solution-Overview/DialogOverviewFeatures";
import TableOverviewFeatures from "src/views/tables/IT-Solution-Overview/TableOverviewFeatures";
import TableOverviewFeaturesTitle from "src/views/tables/IT-Solution-Overview/TableOverviewFeaturesTitle";
import DialogOverviewFeaturesTitle from "src/views/dialog/IT-Solution-Overview/DialogOverviewFeaturesTitle";

const ITSolutionOverviewFeatures = () => {
  const navigate = useNavigate();
  const searchTimeoutRef = useRef();
  const [loading, setLoading] = useState(false);
  const [overViewFeaturesData, setOverViewFeaturesData] = useState([]);
  const [overViewTableHeaderData, setOverViewTableHeaderData] = useState([]);
  const [tableHeader, setTableHeader] = useState({});
  const [search, setSearch] = useState("");
  const [totalCount, setTotalCount] = useState(0);
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(
    DefaultPaginationSettings.ROWS_PER_PAGE
  );
  const [status, setStatus] = useState("");

  const { id } = useParams(); // Get id from location.state
  const [filteredData, setFilteredData] = useState([]);
  const [searchTerm, setSearchTerm] = useState("");
  // Testimonials
  const [overViewFeaturesDialogOpen, setOverViewFeaturesDialogOpen] =
    useState(false);
  const [overViewFeaturesDialogMode, setOverViewFeaturesDialogMode] =
    useState("add");
  const [overviewTableDataToEdit, setOverviewTableData] = useState(null);

  const [overViewTableTitleOpen, setOverViewTableTitleOpen] = useState(false);
  const [overViewTableTitleMode, setOverViewTableTitleMode] = useState("add");
  const [overViewTableTitleToEdit, setOverViewTableTitleToEdit] =
    useState(null);

  const [overviewDataTableVisible, setOverviewDataTableVisible] =
    useState(false);
  const [disableAddBtn, setDisableAddBtn] = useState(false);

  // Confirmation
  const [confirmationDialogLoading, setConfirmationDialogLoading] =
    useState(false);
  const [confirmationDialogOpen, setConfirmationDialogOpen] = useState(false);
  const [testimonialToDelete, setTestimonialToDelete] = useState(null);
  const [deleteType, setDeleteType] = useState("");

  const toggleOverviewTableTitle = (
    e,
    mode = "add",
    overViewTableTitleToEdit = null
  ) => {
    setOverViewTableTitleOpen((prev) => !prev);
    setOverViewTableTitleMode(mode);
    setOverViewTableTitleToEdit(overViewTableTitleToEdit);
  };

  const toggleRugFormDialog = (
    e,
    mode = "add",
    overviewTableDataToEdit = null
  ) => {
    setOverViewFeaturesDialogOpen((prev) => !prev);
    setOverViewFeaturesDialogMode(mode);
    setOverviewTableData(overviewTableDataToEdit);
  };

  const toggleConfirmationDialog = (e, deletetype, dataToDelete = null) => {
    setConfirmationDialogOpen((prev) => !prev);
    setTestimonialToDelete(dataToDelete);

    setDeleteType(deletetype);
  };

  const fetchData = ({
    currentPage,
    pageSize = DefaultPaginationSettings.ROWS_PER_PAGE,
    search,
    status,
  }) => {
    setLoading(true);
    let params = {
      page: currentPage,
      limit: pageSize,
      search: search,
      status: status,
    };

    axiosInstance
      .get(ApiEndPoints.ITSolutionOverviewFeatures.list(id), { params })
      .then((response) => {
        setOverViewFeaturesData(response.data.data);
        setFilteredData(response.data.data);
        setTotalCount(response.data.totalItems);
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };
  const fetchTitleData = ({
    currentPage,
    pageSize = DefaultPaginationSettings.ROWS_PER_PAGE,
    search,
    status,
  }) => {
    setLoading(true);
    let params = {
      page: currentPage,
      limit: pageSize,
      search: search,
      status: status,
    };

    axiosInstance
      .get(ApiEndPoints.ITSolutionOverviewFeaturesTitle.list(id), { params })
      .then((response) => {
        const responseData = response.data.data;
        setTableHeader(responseData[0]);
        setOverViewTableHeaderData(responseData);
        if (responseData.length > 0) {
          setOverviewDataTableVisible(true);
          setDisableAddBtn(true);
        } else {
          setOverviewDataTableVisible(false);
          setDisableAddBtn(false);
        }
        setTotalCount(response.data.totalItems);
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  useEffect(() => {
    fetchTitleData({
      currentPage: currentPage,
      pageSize: pageSize,
      search: search,
      status: status,
    });
    fetchData({
      currentPage: currentPage,
      pageSize: pageSize,
      search: search,
      status: status,
    });
  }, [currentPage, pageSize, search, status]);

  // const handleSearchChange = (e) => {
  //   if (searchTimeoutRef.current) {
  //     clearTimeout(searchTimeoutRef.current);
  //   }

  //   searchTimeoutRef.current = setTimeout(() => {
  //     setSearch(e.target.value);
  //   }, 500);
  // };

  const handleSearchChange = (event) => {
    const value = event.target.value;
    setSearchTerm(value);

    // Filter overviewData based on searchTerm
    const filtered = overViewFeaturesData.filter(
      (item) => item.feature.toLowerCase().includes(value.toLowerCase()) // Assuming 'name' is the field to search
    );
    setFilteredData(filtered);
  };

  const onConfirmDelete = useCallback(
    (e) => {
      e?.preventDefault();
      setConfirmationDialogLoading(true);

      const deleteUrl =
        deleteType === "deleteTableTitle"
          ? ApiEndPoints.ITSolutionOverviewFeaturesTitle.delete(
              testimonialToDelete.id
            )
          : ApiEndPoints.ITSolutionOverviewFeatures.delete(
              testimonialToDelete.id
            );
      axiosInstance
        .delete(deleteUrl)
        .then((response) => response.data)
        .then((response) => {
          deleteType === "deleteTableTitle"
            ? fetchTitleData({
                currentPage: currentPage,
                pageSize: pageSize,
                search: search,
              })
            : fetchData({
                currentPage: currentPage,
                pageSize: pageSize,
                search: search,
              });
          toggleConfirmationDialog();
          toastSuccess(response.message);
        })
        .catch((error) => {
          toastError(error);
        })
        .finally(() => {
          setConfirmationDialogLoading(false);
        });
    },
    [currentPage, testimonialToDelete, pageSize, search, deleteType]
  );

  return (
    <>
      <Grid container rowGap={10}>
        <Grid item container spacing={4} className="match-height">
          <PageHeader
            title={
              <Typography variant="h5">
                <Translations text="Overview Table Title" />
              </Typography>
            }
            action={
              <Button
                variant="contained"
                disabled={disableAddBtn}
                onClick={toggleOverviewTableTitle}
              >
                Add Title
              </Button>
            }
          />
          <Grid item xs={12}>
            <Card>
              <Box sx={{ p: 5 }}>
                <TableOverviewFeaturesTitle
                  loading={loading}
                  rows={overViewTableHeaderData}
                  totalCount={totalCount}
                  setCurrentPage={setCurrentPage}
                  currentPage={currentPage}
                  setPageSize={setPageSize}
                  pageSize={pageSize}
                  toggleDelete={toggleConfirmationDialog}
                  toggleEdit={toggleOverviewTableTitle}
                />
              </Box>
            </Card>
          </Grid>
        </Grid>
        {overviewDataTableVisible && (
          <Grid item container spacing={4} className="match-height">
            <PageHeader
              title={
                <Typography variant="h5">
                  <Translations text="Overview Table Data" />
                </Typography>
              }
              action={
                <Button variant="contained" onClick={toggleRugFormDialog}>
                  Add Data
                </Button>
              }
            />

            <Grid item xs={12}>
              <Card>
                <Box
                  sx={{
                    p: 5,
                    pb: 0,
                    display: "flex",
                    flexWrap: "wrap",
                    alignItems: "center",
                    justifyContent: "end",
                  }}
                >
                  <TextField
                    type="search"
                    size="small"
                    placeholder="Search"
                    onChange={handleSearchChange}
                  />
                </Box>
                <Box sx={{ p: 5 }}>
                  <TableOverviewFeatures
                    search={search}
                    loading={loading}
                    rows={filteredData}
                    totalCount={totalCount}
                    setCurrentPage={setCurrentPage}
                    currentPage={currentPage}
                    setPageSize={setPageSize}
                    pageSize={pageSize}
                    toggleDelete={toggleConfirmationDialog}
                    toggleEdit={toggleRugFormDialog}
                    overViewTableHeaderData={overViewTableHeaderData}
                    tableHeader={tableHeader}
                  />
                </Box>
              </Card>
            </Grid>
          </Grid>
        )}
      </Grid>

      <DialogOverviewFeaturesTitle
        mode={overViewTableTitleMode}
        open={overViewTableTitleOpen}
        toggle={toggleOverviewTableTitle}
        dataToEdit={overViewTableTitleToEdit}
        onSuccess={() => {
          fetchTitleData({
            currentPage: currentPage,
            pageSize: pageSize,
          });
        }}
      />
      <DialogOverviewFeatures
        mode={overViewFeaturesDialogMode}
        open={overViewFeaturesDialogOpen}
        toggle={toggleRugFormDialog}
        dataToEdit={overviewTableDataToEdit}
        overViewTableHeaderData={tableHeader}
        onSuccess={() => {
          fetchData({
            currentPage: currentPage,
            pageSize: pageSize,
          });
        }}
      />
      <DialogConfirmation
        loading={confirmationDialogLoading}
        title={
          deleteType === "deleteTableTitle"
            ? "Delete Table Title"
            : `Delete Overview ${tableHeader?.title_1}`
        }
        subtitle={
          deleteType === "deleteTableTitle"
            ? "Are you sure you want to delete this Table Title"
            : `Are you sure you want to delete this ${tableHeader?.title_1}?`
        }
        open={confirmationDialogOpen}
        toggle={toggleConfirmationDialog}
        onConfirm={onConfirmDelete}
      />
    </>
  );
};

export default ITSolutionOverviewFeatures;
